using System;
using Xunit;
using _module;

namespace PatientStore.Tests
{
    public class PatientStoreDatabaseIOTests
    {
        [Fact]
        public void OpenConnection_ValidConnectionString_ReturnsNonZeroHashCode()
        {
            // Arrange: use a connection string that will fail to connect, but OpenConnection should throw before returning.
            // We expect an exception because no real DB is available.
            var connString = "Server=localhost;Database=WorkflowDb;Trusted_Connection=True;TrustServerCertificate=True";

            // Act & Assert
            Assert.ThrowsAny<Exception>(() => PatientStore.OpenConnection(connString));
        }

        [Fact]
        public void OpenConnection_InvalidConnectionString_Throws()
        {
            // Arrange
            var connString = "Server=invalid-host;Database=WorkflowDb;Trusted_Connection=True;TrustServerCertificate=True";

            // Act & Assert
            Assert.ThrowsAny<Exception>(() => PatientStore.OpenConnection(connString));
        }

        [Fact]
        public void CloseConnection_DoesNotThrow()
        {
            // Act
            PatientStore.CloseConnection(12345);

            // Assert: no exception means success
            Assert.True(true);
        }

        [Fact]
        public void BeginTransaction_ReturnsSameId()
        {
            // Act
            var txId = PatientStore.BeginTransaction(42);

            // Assert
            Assert.Equal(42, txId);
        }

        [Fact]
        public void CommitTransaction_DoesNotThrow()
        {
            // Act
            PatientStore.CommitTransaction(42);

            // Assert
            Assert.True(true);
        }

        [Fact]
        public void RollbackTransaction_DoesNotThrow()
        {
            // Act
            PatientStore.RollbackTransaction(42);

            // Assert
            Assert.True(true);
        }

        [Fact]
        public void QueryDb_NoDatabase_Throws()
        {
            // Arrange: clear env var to use default localhost connection
            Environment.SetEnvironmentVariable("PatientStore__ConnectionString", null);

            // Act & Assert
            Assert.ThrowsAny<Exception>(() => PatientStore.QueryDb("SELECT 1"));
        }

        [Fact]
        public void ExecuteDb_NoDatabase_Throws()
        {
            // Arrange
            Environment.SetEnvironmentVariable("PatientStore__ConnectionString", null);

            // Act & Assert
            Assert.ThrowsAny<Exception>(() => PatientStore.ExecuteDb("INSERT INTO Patients (Id) VALUES (1)"));
        }

        [Fact]
        public void QueryDb_EmptySql_Throws()
        {
            // Arrange
            Environment.SetEnvironmentVariable("PatientStore__ConnectionString", null);

            // Act & Assert
            Assert.ThrowsAny<Exception>(() => PatientStore.QueryDb(""));
        }

        [Fact]
        public void ExecuteDb_NullSql_Throws()
        {
            // Arrange
            Environment.SetEnvironmentVariable("PatientStore__ConnectionString", null);

            // Act & Assert
            Assert.ThrowsAny<Exception>(() => PatientStore.ExecuteDb(null));
        }
    }
}

