using System;
using Xunit;
using PatientStore;

namespace PatientStore.Tests
{
    public class PatientStoreHealthcareIOTests
    {
        [Fact]
        public void GetPatient_ReturnsEmptyJsonObject()
        {
            // Act
            var result = HealthcareIO.GetPatient("p1");

            // Assert
            Assert.Equal("{}", result);
        }

        [Fact]
        public void GetPatient_NullId_ReturnsEmptyJsonObject()
        {
            // Act
            var result = HealthcareIO.GetPatient(null);

            // Assert
            Assert.Equal("{}", result);
        }

        [Fact]
        public void CreateAppointment_ReturnsNonEmptyGuid()
        {
            // Act
            var result = HealthcareIO.CreateAppointment("p1", DateTime.UtcNow, "Dr. Smith");

            // Assert
            Assert.False(string.IsNullOrWhiteSpace(result));
            Assert.True(Guid.TryParse(result, out _));
        }

        [Fact]
        public void SubmitPrescription_ReturnsSuccessWithGuid()
        {
            // Act
            var (success, prescriptionId, error) = HealthcareIO.SubmitPrescription("p1", "Aspirin", "100mg");

            // Assert
            Assert.True(success);
            Assert.False(string.IsNullOrWhiteSpace(prescriptionId));
            Assert.True(Guid.TryParse(prescriptionId, out _));
            Assert.Equal("", error);
        }

        [Fact]
        public void GetLabResults_ReturnsEmptyJsonObject()
        {
            // Act
            var result = HealthcareIO.GetLabResults("p1", "CBC");

            // Assert
            Assert.Equal("{}", result);
        }

        [Fact]
        public void SubmitInsuranceClaim_ReturnsNonEmptyGuid()
        {
            // Act
            var result = HealthcareIO.SubmitInsuranceClaim("p1", 100.50m, "99213");

            // Assert
            Assert.False(string.IsNullOrWhiteSpace(result));
            Assert.True(Guid.TryParse(result, out _));
        }

        [Fact]
        public void AuditAccess_ReturnsTrue()
        {
            // Act
            var result = HealthcareIO.AuditAccess("user1", "read", "patient/p1");

            // Assert
            Assert.True(result);
        }
    }
}

