using System;
using System.IO;
using Xunit;
using AdminCLI;

namespace AdminCLI.Tests
{
    public class AdminCLIConsoleIOTests
    {
        [Fact]
        public void PrintLine_WritesLineToConsole()
        {
            // Arrange
            var originalOut = Console.Out;
            using var sw = new StringWriter();
            Console.SetOut(sw);

            try
            {
                // Act
                ConsoleIO.PrintLine("Hello");

                // Assert
                Assert.Equal("Hello" + Environment.NewLine, sw.ToString());
            }
            finally
            {
                Console.SetOut(originalOut);
            }
        }

        [Fact]
        public void Print_WritesWithoutNewline()
        {
            // Arrange
            var originalOut = Console.Out;
            using var sw = new StringWriter();
            Console.SetOut(sw);

            try
            {
                // Act
                ConsoleIO.Print("Hello");

                // Assert
                Assert.Equal("Hello", sw.ToString());
            }
            finally
            {
                Console.SetOut(originalOut);
            }
        }

        [Fact]
        public void PrintLine_NullMessage_WritesEmptyLine()
        {
            // Arrange
            var originalOut = Console.Out;
            using var sw = new StringWriter();
            Console.SetOut(sw);

            try
            {
                // Act
                ConsoleIO.PrintLine(null);

                // Assert
                Assert.Equal(Environment.NewLine, sw.ToString());
            }
            finally
            {
                Console.SetOut(originalOut);
            }
        }

        [Fact]
        public void ReadLine_ReturnsEmptyWhenNoInput()
        {
            // Arrange
            var originalIn = Console.In;
            using var sr = new StringReader("");
            Console.SetIn(sr);

            try
            {
                // Act
                var result = ConsoleIO.ReadLine();

                // Assert
                Assert.Equal("", result);
            }
            finally
            {
                Console.SetIn(originalIn);
            }
        }

        [Fact]
        public void ReadLine_ReturnsInputLine()
        {
            // Arrange
            var originalIn = Console.In;
            using var sr = new StringReader("test input");
            Console.SetIn(sr);

            try
            {
                // Act
                var result = ConsoleIO.ReadLine();

                // Assert
                Assert.Equal("test input", result);
            }
            finally
            {
                Console.SetIn(originalIn);
            }
        }
    }
}
